GENERATORS: list[Callable[[random.Random], tuple[str, str]]] = [
    py_simple_function, py_class_with_methods, py_dataclass, py_recursive,
    py_async, py_generator, py_decorator,
    rust_function, rust_struct,
    go_function,
    js_arrow, js_class,
