    name = rng.choice(["normalize", "transform", "encode", "decode", "compress"])
    code = f"""pub fn {name}(input: &str) -> Result<String, ParseError> {{
    let trimmed = input.trim();
    if trimmed.is_empty() {{
        return Err(ParseError::Empty);
