def rust_struct(rng: random.Random) -> tuple[str, str]:
    name = rng.choice(["Config", "Settings", "Options", "State"])
    code = f"""pub struct {name} {{
    pub timeout: u64,
    pub retries: u32,
    name: String,
}}

impl {name} {{
    pub fn new(name: String) -> Self {{
        {name} {{ timeout: 30, retries: 3, name }}
    }}

