    obj = extract_json(response)
    if not isinstance(obj, dict):
        return 0.0
    relevant = [(k, v) for k, v in obj.items() if k in types]
    if not relevant:
        return 1.0  # vacuously correct (other sub-scores penalize)
    correct = 0
    for k, v in relevant:
        expected = types[k]
