                "_doctest_summary": {"reason": "no doctests run",
                                     "exit_code": proc.returncode,
                                     "stderr_head": stderr[:300]}}
    # Count failures via the "Failed example:" header.
    failed = stdout.count("Failed example:")
    passed = max(0, tried - failed)
